import {diceThemes} from '../features/dice-themes.mjs';
import {preferences,applyPreferences} from './preferences.mjs';
import {createAccountClient} from '../account/client.mjs';
const swatch='<svg viewBox="0 0 100 110" aria-hidden="true" class="dice-swatch"><path d="M50 3 95 28v54l-45 25L5 82V28Z M50 3 25 70 95 28 M5 28l70 42-25 37 M5 82l20-12h50l20 12 M50 3l25 67"/><text x="50" y="59">20</text></svg>';
export async function openDiceThemes({onChoose}={}){
 const existing=document.querySelector('[data-dice-theme-dialog]');if(existing){if(!existing.open)existing.showModal();return;}
 const dialog=document.createElement('dialog');dialog.dataset.diceThemeDialog='';dialog.className='dice-theme-dialog';dialog.setAttribute('aria-label','Customize dice');
 dialog.innerHTML='<header><h2>Your dice</h2><button type="button" class="button" data-close-dice aria-label="Close dice themes">×</button></header><section class="dice-custom-editor"><div class="dice-custom-swatch">'+swatch+'</div><div class="dice-custom-controls"><label>Shape<select data-custom="shape"><option value="standard">Polyhedral</option><option value="gemstone">Gemstone</option></select></label><label>Finish<select data-custom="material"><option value="polished">Polished</option><option value="glass">Glass</option><option value="galaxy">Galaxy</option><option value="metal">Metal</option></select></label><label>Color<input data-custom="color" type="color"></label><button class="button primary" data-use-custom type="button">Use custom dice</button></div></section><p class="dice-picker-status" role="status" aria-live="polite"></p><h3>Presets</h3><div class="dice-theme-grid">'+diceThemes.map(t=>'<button type="button" class="dice-theme-card" data-dice-choice="'+t.id+'" aria-pressed="false"><span class="dice-theme-art">'+(t.texture?'<img class="dice-theme-texture" src="'+t.texture+'" alt="" loading="lazy">':'')+swatch+'</span><strong>'+t.name+'</strong></button>').join('')+'</div><footer><label>Preview roll <select data-preview-die><option>2d6</option><option>1d20</option><option>1d4</option><option>1d8</option><option>1d10</option><option>1d12</option><option>1d100</option></select></label><button type="button" class="button" data-preview-roll>Roll on page</button></footer>';
 document.body.append(dialog);dialog.showModal();let saves=Promise.resolve(),ticket=0;
 const client=createAccountClient(),status=dialog.querySelector('[role=status]');
 function paint(){const custom=preferences.diceOptions;for(const node of dialog.querySelectorAll('[data-custom]'))node.value=custom[node.dataset.custom];const sample=dialog.querySelector('.dice-custom-swatch');sample.dataset.finish=custom.material;sample.dataset.shape=custom.shape;sample.style.setProperty('--dice-color',custom.color);dialog.querySelector('[data-use-custom]').setAttribute('aria-pressed',String(custom.enabled));for(const card of dialog.querySelectorAll('[data-dice-choice]'))card.setAttribute('aria-pressed',String(!custom.enabled&&preferences.diceTheme===card.dataset.diceChoice));}
 function choose(patch){applyPreferences({...preferences,...patch});paint();const own=++ticket,snapshot={...preferences};status.textContent='Saving…';saves=saves.catch(()=>{}).then(async()=>{try{if(onChoose)await onChoose(patch);else{if(!client.user)await client.restore();await client.update({preferences:snapshot});}if(own===ticket&&dialog.isConnected)status.textContent='Saved.';}catch{if(own===ticket&&dialog.isConnected)status.textContent='Selected on this page. Could not save; select again to retry.';}});}
 const custom=()=>choose({diceTheme:'default',diceOptions:{...preferences.diceOptions,enabled:true,...Object.fromEntries([...dialog.querySelectorAll('[data-custom]')].map(node=>[node.dataset.custom,node.value]))}});
 dialog.querySelector('.dice-custom-editor').onchange=custom;dialog.querySelector('[data-use-custom]').onclick=custom;
 const close=()=>{dialog.close();dialog.remove();};dialog.querySelector('[data-close-dice]').onclick=close;dialog.addEventListener('cancel',event=>{event.preventDefault();close();});
 dialog.addEventListener('click',event=>{const button=event.target.closest('[data-dice-choice]');if(button)choose({diceTheme:button.dataset.diceChoice,diceOptions:{...preferences.diceOptions,enabled:false}});});
 dialog.querySelector('[data-preview-roll]').onclick=async()=>{
  const notation=dialog.querySelector('[data-preview-die]').value;
  if(preferences.diceTheme==='classic'&&!preferences.diceOptions.enabled){const [qty,sides]=notation.split('d').map(Number),values=Array.from({length:qty},()=>1+Math.floor(crypto.getRandomValues(new Uint32Array(1))[0]/4294967296*sides));status.textContent='Preview: '+values.join(' + ')+' = '+values.reduce((a,b)=>a+b,0);return;}
  close();const {show3DDice}=await import('./dice-3d.mjs');void show3DDice(null,{notation:preferences.diceTheme==='genesys'&&!preferences.diceOptions.enabled?[{qty:1,sides:'ability'},{qty:1,sides:'proficiency'},{qty:1,sides:'boost'}]:notation});
 };paint();
}
